function shuffledDeck(type){return [...CARD_DECKS[type]].sort(()=>Math.random()-.5)}

function cleanName(value) { return String(value || '').trim().slice(0, 18); }
function code() { let c; do c = Math.random().toString(36).slice(2,7).toUpperCase(); while (rooms.has(c)); return c; }
function publicRoom(r) { return { ...r,players:r.players.map(({reconnectToken,connectionId,lastChatAt,...player})=>player),board:BOARD,activeDebt:r.debts?.[0]||null,decks:undefined,offers:undefined,debts:undefined,timeout:undefined }; }
function emitOffers(r){r.players.forEach(player=>io.to(player.id).emit('offers',(r.offers||[]).filter(o=>o.buyerId===player.id||o.sellerId===player.id)));}
function emit(r) {r.lastSavedAt=Date.now();persistRooms();io.to(r.code).emit('state', publicRoom(r));emitOffers(r); }
function log(r, message) { r.log.unshift(message); r.log = r.log.slice(0, 20); }
function notify(r,title,text,type='info',target){io.to(target||r.code).emit('gameToast',{title,text,type,id:Date.now()+Math.random()});}
function current(r) { return r.players[r.turn]; }
function roomSettings(r){r.settings={turnDuration:0,disconnectGrace:30,initialMoney:150000,rules:{},...(r.settings||{})};r.settings.turnDuration=0;r.settings.rules={salaryOnStart:true,doubleRentFullGroup:true,extraTurnOnDoubles:true,tripleDoublesJail:true,allowExpropriation:true,allowPropertySwap:true,...(r.settings.rules||{})};return r.settings}
function startTurnClock(r,remaining){const seconds=roomSettings(r).turnDuration;r.turnPaused=false;r.pauseReason=null;r.hostCanSkipAt=null;r.pausedRemaining=null;r.turnDeadline=seconds?Date.now()+(remaining??seconds*1000):null}
function pauseTurnForDisconnect(r){if(r.status!=='playing'||!current(r)||current(r).connected!==false)return;r.pausedRemaining=r.turnDeadline?Math.max(5000,r.turnDeadline-Date.now()):null;r.turnDeadline=null;r.turnPaused=true;r.pauseReason='disconnect';r.hostCanSkipAt=Date.now()+roomSettings(r).disconnectGrace*1000}
function resumeTurnAfterReconnect(r,p){if(r.status==='playing'&&current(r)?.id===p.id&&r.turnPaused&&r.pauseReason==='disconnect')startTurnClock(r,r.pausedRemaining||undefined)}
function defaultStats(){return{rentCollected:0,rentPaid:0,spacesTraveled:0,laps:0,rolls:0,doubles:0,peakDebt:0,propertiesBought:0,housesBuilt:0,hotelsBuilt:0,cardsDrawn:0}}
function statsOf(player){player.stats={...defaultStats(),...(player.stats||{})};return player.stats}
function buildFinalResults(r){const results=r.players.map(player=>{const positions=Object.entries(r.owners).filter(([,owner])=>owner===player.id).map(([position])=>Number(position)),propertyValue=positions.reduce((sum,position)=>sum+(BOARD[position].price||0),0),constructionValue=positions.reduce((sum,position)=>{const tile=BOARD[position],development=r.buildings[position];if(!development)return sum;return sum+(development.hotel?(tile.houseCost*4+tile.hotelCost):(development.houses||0)*tile.houseCost)},0),debt=(r.debts||[]).filter(item=>item.debtorId===player.id).reduce((sum,item)=>sum+item.amount,0),netWorth=player.money+propertyValue+constructionValue-debt;return{id:player.id,name:player.name,color:player.color,token:player.token,bankrupt:player.bankrupt,cash:player.money,propertyValue,constructionValue,debt,netWorth,properties:positions.length,stats:{...statsOf(player)}}}).sort((a,b)=>b.netWorth-a.netWorth);results.forEach((result,index)=>result.rank=index+1);r.finalResults=results;return results}
function nextTurn(r) {
  if (r.players.filter(p => !p.bankrupt).length <= 1) {
    r.status = 'finished';
    const champion=r.players.find(p => !p.bankrupt);r.winner=champion?.name;r.winnerId=champion?.id;buildFinalResults(r);
    log(r, `${r.winner || 'Nadie'} gana la partida.`);
    r.turnDeadline=null;r.turnPaused=false;
    return;
  }
  if(r.extraTurn){r.extraTurn=false;r.phase='notice';r.resumePhase='roll';r.dice=null;r.pending=null;r.gameNotice={type:'double',title:'¡DOBLES! Tienes otro turno',text:`${current(r).name} vuelve a lanzar los dados por haber obtenido dobles.`};startTurnClock(r);log(r,`${current(r).name} vuelve a tirar por obtener dobles.`);return;}
  do r.turn = (r.turn + 1) % r.players.length; while (r.players[r.turn].bankrupt);
  while(current(r).skipTurns>0){current(r).skipTurns--;log(r,`${current(r).name} pierde este turno.`);notify(r,'Turno perdido',`${current(r).name} pierde este turno por el efecto de una carta.`,'warning');do r.turn=(r.turn+1)%r.players.length;while(r.players[r.turn].bankrupt);}
  r.doubles=0;
  r.phase = 'roll';r.resumePhase=null;r.gameNotice=null;r.dice=null;r.pending=null;r.specialEvent=null;r.moveMode=null;
  startTurnClock(r);
  notify(r,'Es tu turno','Lanza los dados cuando estés listo.','turn',current(r).id);
}
function charge(r,player,amount,recipient,reason='Pago pendiente'){
  amount=Math.max(0,Math.floor(amount));if(player.money>=amount){player.money-=amount;if(recipient)recipient.money+=amount;return true;}
  r.debts.push({id:Math.random().toString(36).slice(2,10),debtorId:player.id,creditorId:recipient?.id||null,creditorName:recipient?.name||'Banco',amount,reason});
  statsOf(player).peakDebt=Math.max(statsOf(player).peakDebt,amount);
  log(r,`${player.name} debe reunir $${amount.toLocaleString('es-MX')} para cubrir: ${reason}.`);notify(r,'Pago pendiente',`${player.name} no tiene efectivo suficiente y debe conseguir $${amount.toLocaleString('es-MX')}.`,'danger');return false;
}
function land(r, p, total) {
  const tile = BOARD[p.position];
  if (tile.type === 'goJail') { p.position=10;p.jailed=3;r.extraTurn=false;r.moveMode='deport';r.specialEvent={type:'deported',title:'Pase a Deportado',text:'Tu conducta como turista te envía directamente a Deportado. No recibes sueldo.'};r.phase='special';return log(r, `${p.name} fue enviado a Deportado.`); }
  if (tile.type === 'jail') {r.specialEvent={type:'visit',title:'Visita a Deportado',text:'Estás solamente de visita. No recibes ningún castigo y terminarás tu turno normalmente.'};r.phase='special';return;}
  if (tile.type === 'rest') {r.specialEvent={type:'australia',title:'Un día en Australia',text:'Disfruta los canguros y el paisaje. Aquí no pagas ni recibes dinero. ¿Quieres retar al canguro a muerte?',challenge:true};r.phase='special';return;}
  if (tile.type === 'tax') { charge(r,p,tile.amount); r.phase='end'; return log(r, `${p.name} pagó $${tile.amount}.`); }
  if (tile.type === 'email' || tile.type === 'fax') {
    r.pending={deck:tile.type};r.phase='draw';return log(r,`${p.name} debe tomar una carta de ${tile.type==='fax'?'Correo':'Mensaje'}.`);
  }
  if (['property','transport','diplomatic'].includes(tile.type)) {
    const ownerId=r.owners[p.position];
    if (!ownerId) { r.pending={position:p.position}; r.phase='decision'; return; }
    if (ownerId !== p.id) {
      const owner=r.players.find(x=>x.id===ownerId); let rent=tile.rent;
      if(r.mortgages[p.position]){r.phase='end';log(r,`${tile.name} está hipotecada y no cobra renta.`);notify(r,'Propiedad hipotecada',`${p.name} no paga renta en ${tile.name}.`,'info');return;}
      if(tile.type==='transport'){const count=Object.entries(r.owners).filter(([pos,id])=>id===ownerId&&BOARD[pos].type==='transport').length;rent=[0,2500,5000,10000,20000][count];}
      if(tile.type==='diplomatic'){const count=Object.entries(r.owners).filter(([pos,id])=>id===ownerId&&BOARD[pos].type==='diplomatic').length;rent=total*(count===2?1000:500);}
      if(tile.type==='property'){const development=r.buildings[p.position]||{houses:0,hotel:false};rent=tile.rents[development.hotel?5:development.houses];const block=BOARD.map((x,i)=>({...x,i})).filter(x=>x.group===tile.group);if(roomSettings(r).rules.doubleRentFullGroup&&!development.hotel&&!development.houses&&block.every(x=>r.owners[x.i]===ownerId)){rent*=2;notify(r,'Bloque completo',`${owner.name} posee todo el bloque de ${tile.name}; la renta se duplica.`,'rent');}}
      if(owner.rentBoost){rent*=2;owner.rentBoost=false;notify(r,'Temporada alta',`${owner.name} usa su carta y duplica esta renta.`,'rent');}
      if(!charge(r,p,rent,owner,`Renta de ${tile.name}`)){r.debtResumePhase='end';r.phase='debt';return;}statsOf(owner).rentCollected+=rent;statsOf(p).rentPaid+=rent;log(r, `${p.name} pagó $${rent} a ${owner.name}.`);
      notify(r,'Pago de renta',`${p.name} paga $${rent.toLocaleString('es-MX')} a ${owner.name} por ${tile.name}.`,'rent');
      if(tile.type==='diplomatic'){r.specialEvent={type:'diplomatic',title:tile.name,text:`${owner.name} es propietario. La tirada fue ${total} y la renta es $${rent.toLocaleString('es-MX')}.`};r.phase='special';return;}
    }
  }
  r.phase='end';
}
function drawFromDeck(r,type,p){
  statsOf(p).cardsDrawn++;
  if(!r.decks[type]?.length)r.decks[type]=shuffledDeck(type);const card=r.decks[type].shift();let resolvedText=card.text;r.cardChoice=null;
  if(!card.keep)r.decks[type].push(card);if(card.keep)p.cards.push({type:card.keep,title:card.title});
  if(card.start){r.deferredCardEffect={type:'moveTo',position:0};}else if(card.goJail){r.deferredCardEffect='goJail';}else if(card.money<0)charge(r,p,-card.money,null,card.title);else if(card.money)p.money+=card.money;
  if(card.moveTo!==undefined)r.deferredCardEffect={type:'moveTo',position:card.moveTo};else if(card.moveSteps)r.deferredCardEffect={type:'moveSteps',steps:card.moveSteps};
  if(card.buildingFee){const owned=Object.entries(r.buildings).filter(([position])=>r.owners[position]===p.id),houses=owned.reduce((sum,[,development])=>sum+(development.houses||0),0),hotels=owned.filter(([,development])=>development.hotel).length,amount=houses*Math.abs(card.buildingFee.house)+hotels*Math.abs(card.buildingFee.hotel),insuranceIndex=p.cards.findIndex(saved=>saved.type==='repairInsurance');if(card.buildingFee.house<0&&amount&&insuranceIndex>=0){p.cards.splice(insuranceIndex,1);resolvedText+=` Tu Seguro de mantenimiento cubrió los ${houses} casa(s) y ${hotels} hotel(es): no pagas $${amount.toLocaleString('es-MX')}.`;}else{if(amount){if(card.buildingFee.house<0)charge(r,p,amount,null,card.title);else p.money+=amount;}resolvedText+=` Resultado: ${houses} casa(s), ${hotels} hotel(es), ${card.buildingFee.house<0?'pagas':'recibes'} $${amount.toLocaleString('es-MX')}.`;}}
  if(card.choosePlayer){if(r.players.some(player=>player.id!==p.id&&!player.bankrupt))r.cardChoice={type:'player',playerId:p.id,amount:card.choosePlayer.amount,title:card.title};else resolvedText+=' No quedan otros jugadores disponibles.';}
  if(card.payEach)r.players.filter(x=>x.id!==p.id&&!x.bankrupt).forEach(other=>charge(r,p,card.payEach,other,card.title));
  if(card.collectEach)r.players.filter(x=>x.id!==p.id&&!x.bankrupt).forEach(other=>charge(r,other,card.collectEach,p,card.title));
  if(card.loseTurn)p.skipTurns++;
  r.drawnCard={deck:type,title:card.title,text:resolvedText,player:p.name,kept:Boolean(card.keep),requiresChoice:Boolean(r.cardChoice)};r.card=resolvedText;r.pending=null;r.phase='card';log(r,`${p.name} tomó «${card.title}».`);
}
function blockPositions(group){return BOARD.map((tile,position)=>({tile,position})).filter(x=>x.tile.group===group).map(x=>x.position)}
function developmentLevel(r,position){const d=r.buildings[position];return d?.hotel?5:d?.houses||0}
function expropriationOptions(r,p){const groups=[...new Set(BOARD.filter(tile=>tile.type==='property').map(tile=>tile.group))],options=[];groups.forEach(group=>{const block=blockPositions(group),missing=block.filter(position=>r.owners[position]!==p.id);if(missing.length!==1||block.some(position=>developmentLevel(r,position)>0))return;const position=missing[0],tile=BOARD[position],owner=r.players.find(player=>player.id===r.owners[position]);if(r.mortgages[position])return;options.push({position,name:tile.name,group,ownerName:owner?.name||'Banco',cost:owner?tile.rents[0]:Math.max(0,tile.price-1000)})});return options}
