  socket.on('declareBankruptcy', () => {const r=rooms.get(socket.data.room),debt=r?.debts?.[0],debtor=r?.players.find(p=>p.id===socket.id);if(!r||!debt||debt.debtorId!==socket.id||!debtor)return;const creditor=r.players.find(p=>p.id===debt.creditorId);let liquidation=0;Object.keys(r.buildings).forEach(pos=>{if(r.owners[pos]!==debtor.id)return;const d=r.buildings[pos],tile=BOARD[pos];liquidation+=d.hotel?Math.floor(tile.hotelCost/2):d.houses*Math.floor(tile.houseCost/2);delete r.buildings[pos];});debtor.money+=liquidation;if(creditor){creditor.money+=Math.max(0,debtor.money);let interest=0;Object.keys(r.owners).forEach(pos=>{if(r.owners[pos]===debtor.id){r.owners[pos]=creditor.id;if(r.mortgages[pos])interest+=Math.ceil(BOARD[pos].price*.05);}});if(interest)charge(r,creditor,interest,null,'Intereses de propiedades hipotecadas recibidas');}else Object.keys(r.owners).forEach(pos=>{if(r.owners[pos]===debtor.id){delete r.owners[pos];delete r.mortgages[pos];}});debtor.money=0;debtor.bankrupt=true;r.offers=r.offers.filter(o=>o.buyerId!==debtor.id&&o.sellerId!==debtor.id);r.debts=r.debts.filter(d=>d.debtorId!==debtor.id);log(r,`${debtor.name} se declaró en quiebra${liquidation?` y liquidó construcciones por $${liquidation.toLocaleString('es-MX')}`:''}.`);notify(r,'Quiebra declarada',creditor?`${debtor.name} entrega sus bienes a ${creditor.name}.`:`${debtor.name} devuelve sus bienes al banco.`,'danger');if(r.debts.length){r.phase='debt';}else if(current(r)?.id===debtor.id){r.phase='end';nextTurn(r);}else{r.phase=r.debtResumePhase||'end';r.debtResumePhase=null;}emit(r);});
  socket.on('makeOffer', ({sellerId,position,amount}, acknowledge) => {const r=rooms.get(socket.data.room),buyer=r?.players.find(p=>p.id===socket.id),seller=r?.players.find(p=>p.id===sellerId);position=Number(position);amount=Math.floor(Number(amount));const fail=message=>{if(typeof acknowledge==='function')acknowledge({ok:false,message})};if(!r||r.status!=='playing'||!buyer||!seller||buyer.bankrupt||seller.bankrupt||buyer.id===seller.id)return fail('Oferta inválida.');const tile=BOARD[position];if(r.owners[position]!==seller.id||!tile?.price)return fail('La propiedad ya no pertenece a ese jugador.');if(tile.group&&blockPositions(tile.group).some(pos=>developmentLevel(r,pos)>0))return fail('Primero deben venderse todas las construcciones del bloque.');if(!Number.isFinite(amount)||amount<1||amount>buyer.money)return fail('La cantidad no es válida o supera tu efectivo.');if(r.offers.filter(o=>o.buyerId===buyer.id).length>=12)return fail('Tienes demasiadas ofertas pendientes.');const offer={id:Math.random().toString(36).slice(2,10),buyerId:buyer.id,buyerName:buyer.name,sellerId:seller.id,sellerName:seller.name,position,propertyName:tile.name,amount,createdAt:Date.now()};r.offers.push(offer);emitOffers(r);io.to(seller.id).emit('offerNotification',offer);if(typeof acknowledge==='function')acknowledge({ok:true});});
  socket.on('respondOffer',({offerId,accept},acknowledge)=>{const r=rooms.get(socket.data.room),index=r?.offers.findIndex(o=>o.id===offerId);const fail=message=>{if(typeof acknowledge==='function')acknowledge({ok:false,message})};if(!r||index<0)return fail('La oferta ya no está disponible.');const offer=r.offers[index],seller=r.players.find(p=>p.id===socket.id),buyer=r.players.find(p=>p.id===offer.buyerId),tile=BOARD[offer.position];if(!seller||offer.sellerId!==seller.id)return fail('No puedes responder esta oferta.');r.offers.splice(index,1);if(!accept){emitOffers(r);io.to(buyer.id).emit('offerResult',{accepted:false,propertyName:offer.propertyName});if(typeof acknowledge==='function')acknowledge({ok:true});return;}if(tile.group&&blockPositions(tile.group).some(pos=>developmentLevel(r,pos)>0)){emitOffers(r);return fail('Primero deben venderse todas las construcciones del bloque.');}const interest=r.mortgages[offer.position]?Math.ceil(tile.price*.05):0;if(!buyer||buyer.bankrupt||seller.bankrupt||r.owners[offer.position]!==seller.id||buyer.money<offer.amount+interest){emitOffers(r);io.to(buyer?.id||'').emit('offerResult',{accepted:false,propertyName:offer.propertyName,reason:'La operación ya no es válida.'});return fail('La propiedad o el saldo cambiaron.');}buyer.money-=offer.amount+interest;seller.money+=offer.amount;r.owners[offer.position]=buyer.id;r.offers=r.offers.filter(o=>o.position!==offer.position);log(r,`${seller.name} vendió ${offer.propertyName} a ${buyer.name} por $${offer.amount.toLocaleString('es-MX')}${interest?` y el comprador pagó $${interest.toLocaleString('es-MX')} de intereses`:''}.`);io.to(buyer.id).emit('offerResult',{accepted:true,propertyName:offer.propertyName,amount:offer.amount});emit(r);if(typeof acknowledge==='function')acknowledge({ok:true});});
  socket.on('roll', () => {
    const r=rooms.get(socket.data.room); if(!r||r.status!=='playing'||current(r)?.id!==socket.id||r.phase!=='roll')return;
    const p=current(r); const a=1+Math.floor(Math.random()*6), b=1+Math.floor(Math.random()*6),isDouble=a===b,wasJailed=Boolean(p.jailed); r.dice=[a,b]; r.card=null;
    statsOf(p).rolls++;statsOf(p).spacesTraveled+=a+b;if(isDouble)statsOf(p).doubles++;
    if(p.jailed){if(isDouble){p.jailed=0;r.extraTurn=false;log(r,`${p.name} salió de Deportado con dobles.`);notify(r,'¡Pasaporte recuperado!',`${p.name} obtuvo dobles y sale de Deportado.`,'success');}else if(p.jailed>1){p.jailed--;r.phase='end';log(r,`${p.name} sigue Deportado (${p.jailed} intento(s)).`);notify(r,'Sigue Deportado',`${p.name} no obtuvo dobles. Le quedan ${p.jailed} intento(s).`,'warning');return emit(r);}else{charge(r,p,5000);p.jailed=0;r.extraTurn=false;log(r,`${p.name} agotó sus intentos y pagó la multa obligatoria de $5,000.`);notify(r,'Multa obligatoria',`${p.name} agotó sus intentos y paga $5,000 para continuar.`,'warning');if(p.bankrupt){r.phase='end';return emit(r);}}}
    if(roomSettings(r).rules.extraTurnOnDoubles&&!wasJailed&&isDouble){r.doubles++;r.extraTurn=true;if(roomSettings(r).rules.tripleDoublesJail&&r.doubles>=3){p.position=10;p.jailed=3;r.extraTurn=false;r.moveMode='deport';r.specialEvent={type:'deported',title:'Tres dobles consecutivos',text:'Abusaste de las leyes internacionales y fuiste enviado directamente a Deportado.'};r.phase='special';log(r,`${p.name} obtuvo tres dobles y fue Deportado.`);return emit(r);}notify(r,'¡Dados dobles!',`${p.name} obtuvo ${a} y ${b}. Al terminar esta jugada tendrá un turno extra.`,'double');}else if(!wasJailed){r.doubles=0;r.extraTurn=false;}
    const old=p.position; p.position=(old+a+b)%40; if(p.position<old){statsOf(p).laps++;if(roomSettings(r).rules.salaryOnStart){p.money+=20000;log(r,`${p.name} pasó por la salida y cobró $20,000.`);notify(r,'Sueldo de viajero',`${p.name} pasó por Salida y recibe $20,000.`,'money');}}
    log(r,`${p.name} lanzó ${a} + ${b} y llegó a ${BOARD[p.position].name}.`); land(r,p,a+b); emit(r);
  });
  socket.on('buy', () => { const r=rooms.get(socket.data.room); if(!r||current(r)?.id!==socket.id||r.phase!=='decision')return; const p=current(r), pos=r.pending.position,t=BOARD[pos]; if(p.money>=t.price){p.money-=t.price;r.owners[pos]=p.id;statsOf(p).propertiesBought++;log(r,`${p.name} compró ${t.name} por $${t.price}.`);notify(r,'Nueva propiedad',`${p.name} compra ${t.name} por $${t.price.toLocaleString('es-MX')}.`,'money');} r.pending=null;r.phase='end';emit(r); });
  socket.on('skip', () => { const r=rooms.get(socket.data.room); if(!r||current(r)?.id!==socket.id||r.phase!=='decision')return; r.pending=null;r.phase='end';emit(r); });
